-- Review only the global Hang Power Clean; preserve manual data and histories.
BEGIN;
SELECT id FROM "Exercise" WHERE id='1b7764ca-1826-488e-8734-fc88117ed9dd' FOR UPDATE;
DO $$ BEGIN
 IF EXISTS (SELECT 1 FROM "Exercise" WHERE id='1b7764ca-1826-488e-8734-fc88117ed9dd' AND ("ownerUserId" IS NOT NULL OR name <> 'Hang Power Clean')) THEN RAISE EXCEPTION 'Hang clean identity changed; review manually'; END IF;
 IF EXISTS (SELECT 1 FROM "Exercise" e WHERE e.id='1b7764ca-1826-488e-8734-fc88117ed9dd' AND e."anatomyReview" IS NULL AND (EXISTS (SELECT 1 FROM "ExerciseMuscle" m WHERE m."exerciseId"=e.id AND NOT ((m."muscleGroup"='QUADRICEPS' AND m.role='PRIMARY') OR (m."muscleGroup"='GLUTES' AND m.role='PRIMARY') OR (m."muscleGroup"='HAMSTRINGS' AND m.role='PRIMARY') OR (m."muscleGroup"='CALVES' AND m.role='SECONDARY') OR (m."muscleGroup"='BACK' AND m.role='SECONDARY') OR (m."muscleGroup"='SHOULDERS' AND m.role='SECONDARY') OR (m."muscleGroup"='FOREARMS' AND m.role='SECONDARY') OR (m."muscleGroup"='CORE' AND m.role='SECONDARY') OR (m."muscleGroup"='ADDUCTORS' AND m.role='SECONDARY') OR (m."muscleGroup"='BICEPS' AND m.role='SECONDARY'))) OR (SELECT COUNT(*) FROM "ExerciseMuscle" m WHERE m."exerciseId"=e.id AND m."muscleGroup" NOT IN ('BICEPS','ADDUCTORS')) <> 8)) THEN RAISE EXCEPTION 'Hang clean classification changed; review manually'; END IF;
END $$;
INSERT INTO "ExerciseMuscle" (id,"exerciseId","muscleGroup",role,"createdAt") SELECT gen_random_uuid()::text,e.id,'ADDUCTORS','SECONDARY',CURRENT_TIMESTAMP FROM "Exercise" e WHERE e.id='1b7764ca-1826-488e-8734-fc88117ed9dd' AND e."ownerUserId" IS NULL AND e."anatomyReview" IS NULL ON CONFLICT ("exerciseId","muscleGroup") DO NOTHING;
INSERT INTO "ExerciseMuscle" (id,"exerciseId","muscleGroup",role,"createdAt") SELECT gen_random_uuid()::text,e.id,'BICEPS','SECONDARY',CURRENT_TIMESTAMP FROM "Exercise" e WHERE e.id='1b7764ca-1826-488e-8734-fc88117ed9dd' AND e."ownerUserId" IS NULL AND e."anatomyReview" IS NULL ON CONFLICT ("exerciseId","muscleGroup") DO NOTHING;
UPDATE "Exercise" e SET "anatomyReview"='{"version":"2026-11-10.1","reviewedAt":"2026-11-10T18:00:00.000Z","variant":"Hang Power Clean bilateral com barra livre, início suspenso acima dos joelhos, extensão explosiva e recepção sobre os ombros em agachamento parcial.","aliases":["hang power clean","hang power clean com barra","clean suspenso com recepção alta"],"participants":[{"id":"RECTUS_FEMORIS","label":"Reto femoral","muscleGroup":"QUADRICEPS","role":"PRIMARY","aliases":["quadríceps","quadriceps"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ARNOLD_2010"]},{"id":"VASTUS_LATERALIS","label":"Vasto lateral","muscleGroup":"QUADRICEPS","role":"PRIMARY","aliases":["quadríceps"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ARNOLD_2010","GEISLER_2023"]},{"id":"VASTUS_MEDIALIS","label":"Vasto medial","muscleGroup":"QUADRICEPS","role":"PRIMARY","aliases":["quadríceps"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ARNOLD_2010"]},{"id":"VASTUS_INTERMEDIUS","label":"Vasto intermédio","muscleGroup":"QUADRICEPS","role":"PRIMARY","aliases":["vasto intermediário","quadríceps"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ARNOLD_2010"]},{"id":"GLUTEUS_MAXIMUS","label":"Glúteo máximo","muscleGroup":"GLUTES","role":"PRIMARY","aliases":["glúteos","gluteus maximus"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ARNOLD_2010","GEISLER_2023"]},{"id":"ADDUCTOR_MAGNUS","label":"Adutor magno","muscleGroup":"ADDUCTORS","role":"SECONDARY","aliases":["grande adutor","adductor magnus","adutores"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ARNOLD_2010"]},{"id":"RECTUS_ABDOMINIS","label":"Reto abdominal","muscleGroup":"CORE","role":"SECONDARY","aliases":["abdômen","abdominais","rectus abdominis"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["GEISLER_2023","OPENSTAX_UPPER"]},{"id":"EXTERNAL_OBLIQUE","label":"Oblíquo externo","muscleGroup":"CORE","role":"SECONDARY","aliases":["oblíquos","external oblique","abdômen"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["GEISLER_2023","OPENSTAX_UPPER"]},{"id":"ERECTOR_SPINAE","label":"Eretores da coluna","muscleGroup":"BACK","role":"SECONDARY","aliases":["eretor da espinha","eretores espinhais","lombar","erector spinae"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["GEISLER_2023","OPENSTAX_UPPER"]},{"id":"BICEPS_FEMORIS","label":"Bíceps femoral — cabeça longa","muscleGroup":"HAMSTRINGS","role":"PRIMARY","aliases":["posteriores da coxa","isquiotibiais"],"regions":[{"id":"BICEPS_FEMORIS_LONG_HEAD","label":"Cabeça longa do bíceps femoral","aliases":["bíceps femoral cabeça longa"]}],"emphasizedRegionIds":[],"sourceIds":["ARNOLD_2010"]},{"id":"SEMITENDINOSUS","label":"Semitendíneo","muscleGroup":"HAMSTRINGS","role":"PRIMARY","aliases":["semitendinoso","semitendinosus","posteriores da coxa","isquiotibiais"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ARNOLD_2010"]},{"id":"SEMIMEMBRANOSUS","label":"Semimembranáceo","muscleGroup":"HAMSTRINGS","role":"PRIMARY","aliases":["semimembranoso","semimembranosus","posteriores da coxa","isquiotibiais"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ARNOLD_2010"]},{"id":"FLEXOR_DIGITORUM_SUPERFICIALIS","label":"Flexor superficial dos dedos","muscleGroup":"FOREARMS","role":"SECONDARY","aliases":["flexor digitorum superficialis","pegada"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"FLEXOR_DIGITORUM_PROFUNDUS","label":"Flexor profundo dos dedos","muscleGroup":"FOREARMS","role":"SECONDARY","aliases":["flexor digitorum profundus","pegada"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"FLEXOR_CARPI_ULNARIS","label":"Flexor ulnar do carpo","muscleGroup":"FOREARMS","role":"SECONDARY","aliases":["flexor carpi ulnaris","punho"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"EXTENSOR_CARPI_RADIALIS_BREVIS","label":"Extensor radial curto do carpo","muscleGroup":"FOREARMS","role":"SECONDARY","aliases":["extensor carpi radialis brevis","punho"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"LATISSIMUS_DORSI","label":"Latíssimo do dorso","aliases":["dorsal","grande dorsal","latissimus dorsi"],"muscleGroup":"BACK","role":"SECONDARY","regions":[],"emphasizedRegionIds":[],"sourceIds":["GEISLER_2023","OPENSTAX_UPPER"]},{"id":"TRAPEZIUS","label":"Trapézio","aliases":["trapezio","trapézio","trapezius"],"muscleGroup":"BACK","role":"SECONDARY","regions":[],"emphasizedRegionIds":[],"sourceIds":["GEISLER_2023","OPENSTAX_UPPER"]},{"id":"GASTROCNEMIUS_MEDIAL","label":"Gastrocnêmio medial","muscleGroup":"CALVES","role":"SECONDARY","aliases":["gastrocnêmio","panturrilha medial"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ARNOLD_2010","NSCA_HANG"]},{"id":"GASTROCNEMIUS_LATERAL","label":"Gastrocnêmio lateral","muscleGroup":"CALVES","role":"SECONDARY","aliases":["gastrocnêmio","panturrilha lateral"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ARNOLD_2010","NSCA_HANG"]},{"id":"SOLEUS","label":"Sóleo","muscleGroup":"CALVES","role":"SECONDARY","aliases":["soleus","panturrilha"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ARNOLD_2010","NSCA_HANG"]},{"id":"DELTOID_ANTERIOR","label":"Deltoide anterior","muscleGroup":"SHOULDERS","role":"SECONDARY","aliases":["ombro anterior","deltoide frontal"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER","NSCA_HANG"]},{"id":"BICEPS_BRACHII","label":"Bíceps braquial","muscleGroup":"BICEPS","role":"SECONDARY","aliases":["bíceps"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER","NSCA_HANG"]}],"sources":[{"id":"GEISLER_2023","title":"Geisler et al. — Effects of Expertise on Muscle Activity during the Hang Power Clean and Hang Power Snatch Compared to Snatch and Clean Pulls (2023)","url":"https://doi.org/10.52082/jssm.2023.778","limitation":"27 levantadores, diferentes níveis, 50/70/90% de 1RM. EMG de vasto lateral, glúteo máximo, eretores, reto abdominal e trapézio. Resultados dependem de carga e experiência; não cobrem todos os músculos ou definem ângulos ideais."},{"id":"NSCA_HANG","title":"NSCA — Power Clean From Hang (2022)","url":"https://www.nsca.com/education/articles/kinetic-select/power-clean-from-hang/","limitation":"Guia técnico para início acima dos joelhos, extensão coordenada, giro dos cotovelos, recepção parcial e recuperação. Não é estudo de EMG e não prescreve ângulos universais."},{"id":"ARNOLD_2010","title":"Arnold et al. — A Model of the Lower Limb for Analysis of Human Movement (2010)","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC2903973/","limitation":"Anatomia e modelo funcional do membro inferior. Participação de isquiotibiais, adutor e panturrilhas nesta variação é inferência anatômica, não quantificação de EMG."},{"id":"OPENSTAX_UPPER","title":"OpenStax Anatomy and Physiology 2e — Muscles of the Pectoral Girdle and Upper Limbs","url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/11-5-muscles-of-the-pectoral-girdle-and-upper-limbs","limitation":"Anatomia funcional dos ombros, cotovelos e punhos. Papéis de estabilização e transição são inferências; não comprova intensidade específica de LPO."}],"notes":"Classificação funcional editorial: quadríceps, glúteo máximo e isquiotibiais principais; panturrilhas, adutor magno, trapézio, dorsal, eretores, abdômen, deltoide anterior, bíceps e pegada secundários. As funções variam por fase: a extensão das pernas/quadril acelera a barra, os cotovelos giram após a propulsão e ombros/tronco estabilizam a recepção. Bíceps não é o motor da arrancada inicial. Não há isolamento, ranking de ativação ou intensidade medida. A animação usa tempos e amplitudes ilustrativos, não captura de movimento nem reprodução de um atleta. Superfícies reutilizam identidades anatômicas verificadas e recebem papéis independentes. Sem ênfase regional não demonstrada.","instructions":{"description":"Hang Power Clean bilateral com barra: extensão explosiva e recepção sobre os ombros em agachamento parcial.","setup":"Comece em pé com a barra suspensa e pegada pronada um pouco além dos ombros. Flexione quadris e joelhos para posicionar a barra acima dos joelhos, com o tronco firme e os braços alongados.","execution":"Estenda quadris, joelhos e tornozelos de forma coordenada para acelerar a barra próxima ao corpo. Entre sob a barra e gire os cotovelos para a frente, recebendo-a sobre a parte anterior dos ombros em agachamento parcial. Estabilize e fique em pé.","tips":"A força inicial vem das pernas e do quadril; evite antecipar a puxada com os braços. Na recepção, mantenha os cotovelos à frente e os pés estáveis. Retorne a barra às coxas com controle. A animação é ilustrativa; cores não medem EMG ou intensidade de esforço."}}'::jsonb,"updatedAt"=CURRENT_TIMESTAMP WHERE e.id='1b7764ca-1826-488e-8734-fc88117ed9dd' AND e."ownerUserId" IS NULL AND e."anatomyReview" IS NULL;
COMMIT;
